private boolean assignableFrom(Collection<Class<? extends Parser>> excludeParsers, Class<? extends Parser> p) {
    for (Class<? extends Parser> e : excludeParsers) {
        if (e.isAssignableFrom(p)) {
            return true;
        }
    }
    return false;
}
